// Root cause do bug "recomenda item em pergunta fora de escopo": os cards
// vinham direto da busca vetorial (node "Buscar Contexto"), sem nenhuma
// relação com o que o Agent realmente respondeu.
//
// Por isso o Agent é obrigado (regra 10 do prompt) a fechar toda resposta com
// uma linha "ITENS_SUGERIDOS: id1, id2" ou "ITENS_SUGERIDOS: nenhum". Esse
// node lê essa linha, tira ela do texto visível ao cliente, e só deixa
// passar pros cards os itens da busca cujo item_id o Agent realmente citou.

function normalizarId(valor) {
  return String(valor || '').trim().toLowerCase();
}

const bruto = $json.output || '';
const match = bruto.match(/\n?ITENS_SUGERIDOS:\s*([^\n]*)\s*$/i);

let textoLimpo = bruto;
let idsSugeridos = [];

if (match) {
  textoLimpo = bruto.slice(0, match.index).trim();
  const lista = match[1].trim();
  if (lista && !/^nenhum$/i.test(lista)) {
    idsSugeridos = lista.split(',').map((s) => normalizarId(s)).filter(Boolean);
  }
} else {
  // Agent não seguiu a regra 10 (ex.: resposta de fallback/erro) — não temos
  // sinal de que item foi de fato recomendado, então não mostra cards.
  textoLimpo = bruto;
}

let produtosDisponiveis = [];
try {
  produtosDisponiveis = $('Buscar Contexto').item.json.produtos || [];
} catch (erro) {
  produtosDisponiveis = [];
}

const produtosFiltrados = idsSugeridos.length
  ? produtosDisponiveis.filter((p) => idsSugeridos.includes(normalizarId(p.codigo)))
  : [];

return [{
  json: {
    ...$json,
    output: textoLimpo,
    produtos_filtrados: produtosFiltrados,
  },
}];

const fs = require('fs');
const path = require('path');

// Log tecnico local, sem PII, acesso restrito a equipe tecnica.
const entrada = $('Webhook Chat').item.json.body || {};
const resposta = $json.output || 'Estou com uma instabilidade temporária pra gerar a resposta agora. Pode tentar novamente em alguns instantes?';

// Sinal deterministico de "nao encontrei nada": olha se a busca no catalogo
// (node "Buscar Contexto") voltou vazia. Ajuda a priorizar coleções/FAQ que
// faltam no catálogo ou perguntas fora do escopo do site.
let buscaSemResultado = false;
try {
  const contextoBusca = $('Buscar Contexto').item.json.contexto || '';
  buscaSemResultado = contextoBusca.includes('Nenhuma informação relevante foi encontrada');
} catch (erro) {
  // se o node de busca nem rodou (erro antes dele), nao da pra saber - deixa false
}

const pastaLogs = $env.HARUS_LOGS_PATH || '/data/logs';
const caminho = path.join(pastaLogs, 'conversas.jsonl');

try {
  fs.mkdirSync(pastaLogs, { recursive: true });
  fs.appendFileSync(caminho, JSON.stringify({
    timestamp: new Date().toISOString(),
    usuario_id: entrada.usuario_id || 'anonimo',
    pergunta: entrada.mensagem || '',
    resposta,
    itens_retornados: ($json.produtos_filtrados || []).length,
    busca_sem_resultado: buscaSemResultado,
    erro: !$json.output,
  }) + '\n', 'utf-8');
} catch (erro) {
  // log e best-effort, nunca deve derrubar o fluxo
}

return [{ json: $json }];
